set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
import json,base64,hashlib
from pathlib import Path
data=json.loads('{"rag/service/plan_chat.py": "", "rag/service/retrieval_server.py": "", "rag/eval/tests/test_plan_chat.py": "", "rag/client/plan_chat_query.py": "", "docs/PLAN_CHAT_NL_INTAKE.md": ""}')
for n,b in data.items():
 p=Path(n);backup=Path('deploy/backups/plan-chat-nl-intake')/n
 if p.exists() and not backup.exists():
  backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(p.read_bytes())
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
 assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(base64.b64decode(b)).digest()
print('Synced and verified 5 files')
PY
PYTHONPATH=rag .venv/bin/python -m unittest discover -s rag/eval/tests -p 'test_*.py'
