from pathlib import Path
p=Path('.env');lines=p.read_text().splitlines();lines=[l for l in lines if not l.startswith('RAG_PLAN_CHAT_ENABLED=')];p.write_text('\n'.join(lines)+'\nRAG_PLAN_CHAT_ENABLED=1\n')
PY
