.venv/bin/python - <<'PY'
import json,requests
from pathlib import Path
base='http://127.0.0.1:8100'
health=requests.get(base+'/health',timeout=10).json();assert health['model_ready']
schema=requests.get(base+'/openapi.json',timeout=10).json();assert '/plan/chat' in schema['paths']
before=requests.get(base+'/maps/usage',timeout=10).json()
r=requests.post(base+'/plan/chat',json={'message':'帮我安排洛阳三天，我还没确定出发地点'},timeout=45);r.raise_for_status();answer=r.json()
assert answer['status']=='needs_clarification',answer['status']
assert answer.get('slots',{}).get('days')==3,answer.get('slots')
after=requests.get(base+'/maps/usage',timeout=10).json();assert before['usage']==after['usage'],'unexpected Baidu usage'
report={'unit_tests_passed':150,'health':health,'feature_flag':'RAG_PLAN_CHAT_ENABLED=1','new_baidu_calls':0,'smoke_request':'帮我安排洛阳三天，我还没确定出发地点','smoke_response':answer,'full_73_25_30_rerun':False,'human_review':None}
Path('rag/eval/reports/plan_chat_deployment.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'health':health,'chat_status':answer['status'],'days':answer['slots']['days'],'answer':answer['answer'],'new_baidu_calls':0},ensure_ascii=False))
PY
